SELECT day AS "数据日期",channel AS "渠道ID",battle_type AS "玩法类型",battle_type_name AS "玩法名称",map_id AS "关卡ID",fail_count AS "失败次数",fail_users AS "失败人数",CAST(ROUND(fail_count*1.000000000000/NULLIF(fail_users,0),2) AS decimal(18,2)) AS "人均失败次数",ROUND(avg_time,2) AS "平均失败时长_秒",ROUND(avg_remain,2) AS "平均剩余螺丝数",min_remain AS "最少剩余螺丝数",max_remain AS "最多剩余螺丝数",missing_remain AS "剩余螺丝未上报次数" FROM (SELECT day,channel,battle_type,battle_type_name,map_id,COUNT(*) fail_count,COUNT(DISTINCT pid) fail_users,AVG(battle_time) avg_time,AVG(remain_screw_num) avg_remain,MIN(remain_screw_num) min_remain,MAX(remain_screw_num) max_remain,COUNT_IF(remain_screw_num IS NULL) missing_remain FROM (SELECT * FROM (SELECT f.*,CASE WHEN s.scope=0 THEN '全部渠道' ELSE reg_channel END channel FROM (SELECT * FROM (SELECT e."$part_date" day,u.pid,u.reg_day,u.channel_id reg_channel,e."$part_event" event_name,coalesce(e.battle_type,'未知模式') battle_type,coalesce(nullif(e.battle_type_name,''),e.battle_type,'未知模式') battle_type_name,e.map_id,e.battle_result,e.battle_time,e.remain_screw_num FROM ta.v_event_54 e JOIN (SELECT "#user_id",coalesce(nullif(nb_open_id,''),nullif("#account_id",''),cast("#user_id" AS varchar)) pid,date(min(first_login_time) OVER(PARTITION BY coalesce(nullif(nb_open_id,''),nullif("#account_id",''),cast("#user_id" AS varchar)))) reg_day,coalesce(first_value(channel_id) OVER(PARTITION BY coalesce(nullif(nb_open_id,''),nullif("#account_id",''),cast("#user_id" AS varchar)) ORDER BY first_login_time NULLS LAST),'未知') channel_id FROM ta.v_user_54 WHERE domain='release' AND game_name='yishuajiushangtou') u ON e."#user_id"=u."#user_id" WHERE e.game_name='yishuajiushangtou' AND ${PartDate:date1}) f WHERE ${Selector:selector2}) f CROSS JOIN (VALUES (0),(1)) s(scope)) z WHERE event_name='battle_result' AND battle_result=2) f GROUP BY 1,2,3,4,5) a ORDER BY day DESC,channel,battle_type,map_id